P=Path(__file__).resolve().parent;catalog=json.loads((P/'catalog.json').read_text());summary=json.loads((P/'glass-worksheet-comparison/summary.json').read_text());profile=next(r for r in catalog['profiles'] if r['id']==summary['profile_id']);R=profile['sphere_diameter_m']/2
