 points.append({'id':f"Glass photo roll{r['roll']:g} frame{r['frame']:g}",'type':kind,'ell_m':R,'observed_signature':o.tolist(),'predicted_signature':p.tolist(),'mix_angle_error_deg':a,'magnitude_error_percent':e,'measured_comparison':'Source worksheet contact reconstruction; spin inferred by angular momentum, not independently measured. Published coefficients unchanged.','source_excel_row':r['source_excel_row']})
