ax.scatter([0],[0],marker='*',s=190,color='black',label='Exact agreement');ax.axhline(0,color='#777',linewidth=.8);ax.grid(alpha=.2);ax.set_axisbelow(True);ax.set_xlim(-.5,max(r['mix_angle_error_deg'] for r in points)*1.15);ax.set_xlabel('Velocity–spin mix error (degrees; signature space)');ax.set_ylabel('Combined signature magnitude error (%)');ax.set_title('Published material inputs, no project fitting\n24 glass–glass impacts from the original worksheet');ax.legend(frameon=False,fontsize=9)
